"""Print every registry variant and the intakes it accepts, as dfe-schemas commits it in `registries/elastic-variants.yaml`."""

import sys

import sources

# The output is committed in dfe-schemas, so the header speaks to a reader there.
HEADER = (
    "# Every variant dfe-transform-elastic registers, with the intakes it accepts.\n"
    "# Generated by its scripts/emit_variants.py and synced by its CI, so do not edit by hand.\n"
)


def render(*, declared: dict[str, sources.Source]) -> str:
    """The registry file for *declared*, with the variants and each one's intakes sorted."""
    variants = {}
    for source in declared.values():
        for name in source.registry_names:
            variants[name] = sorted(source.intakes)
    lines = [f"{name}: [{', '.join(variants[name])}]" for name in sorted(variants)]
    return HEADER + "\n".join(lines) + "\n"


def main() -> int:
    sys.stdout.write(render(declared=sources.SOURCES))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
